      "body": "\"In-law\" means relation through marriage. Spouse's father = Father-in-law (सासरे). Sibling's spouse or spouse's sibling = Brother/Sister-in-law.",
      "bodyMr": "विवाहामुळे जोडली गेलेली नाती: जोडीदाराचे वडील = सासरे; जोडीदाराची आई = सासू; पतीचा भाऊ = दीर; पत्नीचा भाऊ = मेहुणा/साला.",
      "formula": "Husband's brother = Deewar (दीर) ; Wife's brother = Mehuna (मेहुणा) -> Both are Brother-in-law",
      "formulaMr": "पतीचा भाऊ = दीर ; पत्नीचा भाऊ = मेहुणा/साला -> इंग्रजीत दोघेही Brother-in-law",
      "example": "Woman points to a man and says: \"His sister is my mother-in-law.\" Man is her husband's maternal uncle (मामा सासरे).",
      "exampleMr": "एका स्त्रीने म्हटले: \"यांची बहीण माझी सासू आहे.\" म्हणजेच तो पुरुष तिच्या पतीचा मामा (मामा सासरे) आहे.",
      "tip": "Daughter-in-law = Son's wife (सून). Son-in-law = Daughter's husband (जावई).",
      "tipMr": "मुलाची पत्नी = सून (Daughter-in-law); मुलीचा पती = जावई (Son-in-law)."
