      "bodyMr": "चिन्हे, त्यांचे अर्थ, लिंग व पिढी फरक एका रेषेत मांडा: + (आई, स्त्री, +१), - (भाऊ, पुरुष, ०), × (वडील, पुरुष, +१), ÷ (मुलगी, स्त्री, -१).",
