      "body": "Sibling's child is at -1 generation. Brother's/Sister's son = Nephew. Brother's/Sister's daughter = Niece.",
      "bodyMr": "भावंडांची मुले (-१ पिढी): भावाचा किंवा बहिणीचा मुलगा = पुतण्या/भाचा (Nephew); भावाची किंवा बहिणीची मुलगी = पुतणी/भाची (Niece).",
      "formula": "Sibling's Son = Nephew ; Sibling's Daughter = Niece",
      "formulaMr": "भावाचा मुलगा = पुतण्या ; बहिणीचा मुलगा = भाचा (दोघांना इंग्रजीत Nephew म्हणतात)",
      "example": "A's brother is B. B's daughter is C. C is A's Niece (पुतणी).",
      "exampleMr": "A चा भाऊ B आहे. B ची मुलगी C आहे. तर C ही A ची पुतणी (Niece) आहे.",
      "tip": "Cousin is 0 generation (Uncle/Aunt's child), whereas Nephew/Niece is -1 generation.",
      "tipMr": "चुलत/मामे भावंडे ही ० पिढीत (Cousin) येतात, तर भाचे/पुतणे हे -१ पिढीत (Nephew/Niece) येतात."
