      "bodyMr": "जर सर्व विधाने हकारात्मक (सर्व / काही) असतील, तर कोणताही नकारात्मक (नाही / काही नाहीत) निश्चित निष्कर्ष कधीही बरोबर असू शकत नाही.",
      "formula": "Positive Statements -> 100% Negative Definite Conclusions are FALSE",
      "formulaMr": "सर्व विधाने हकारात्मक -> नकारात्मक निश्चित निष्कर्ष थेट चुकीचे ठरवा",
