      "body": "When two statements are negative (No A is B, No B is C), no definite conclusion between A and C can be drawn.",
      "bodyMr": "जर दोन विधाने नकारात्मक असतील (कोणताही A हा B नाही, कोणताही B हा C नाही), तर A आणि C मध्ये कोणताही निश्चित संबंध नसतो.",
      "formula": "No + No = No Definite Conclusion (Everything is a possibility)",
