      "example": "\"No pen is pencil. No pencil is eraser.\" -> Definite conclusion between Pen and Eraser is INVALID.",
      "exampleMr": "\"कोणताही पेन पेन्सिल नाही. कोणतीही पेन्सिल रबर नाही.\" -> पेन आणि रबरमधील कोणताही निश्चित निष्कर्ष चुकीचा ठरेल.",
